code_examples.code:
Example

function Trainer(xArray, yArray) {

  this.xArr = xArray;

  this.yArr = yArray;

  this.points = this.xArr.length;

  this.learnc = 0.00001;

  this.weight = 0;

  this.bias = 1;

  this.cost;

this.costError = function() {

  total = 0;

  for (let i = 0; i < this.points; i++) {

    total += (this.yArr[i] - (this.weight * this.xArr[i] + this.bias)) **2;

  }

  return total / this.points;

}

this.train = function(iter) {

  for (let i = 0; i < iter; i++) {

    this.updateWeights();

  }

  this.cost = this.costError();

}

this.updateWeights = function() {

  let wx;

  let w_deriv = 0;

  let b_deriv = 0;

  for (let i = 0; i < this.points; i++) {

    wx = this.yArr[i] - (this.weight * this.xArr[i] + this.bias);

    w_deriv += -2 * wx * this.xArr[i];

    b_deriv += -2 * wx;

  }

  this.weight -= (w_deriv / this.points) * this.learnc;

  this.bias -= (b_deriv / this.points) * this.learnc;

}

function Trainer(xArray, yArray) {

  this.xArr = xArray;

  this.yArr = yArray;

  this.points = this.xArr.length;

  this.learnc = 0.00001;

  this.weight = 0;

  this.bias = 1;

  this.cost;

// Cost Function

this.costError = function() {

  total = 0;

  for (let i = 0; i < this.points; i++) {

    total += (this.yArr[i] - (this.weight * this.xArr[i] + this.bias)) **2;

  }

  return total / this.points;

}

// Train Function

this.train = function(iter) {

  for (let i = 0; i < iter; i++) {

    this.updateWeights();

  }

  this.cost = this.costError();

}

// Update Weights Function

this.updateWeights = function() {

  let wx;

  let w_deriv = 0;

  let b_deriv = 0;

  for (let i = 0; i < this.points; i++) {

    wx = this.yArr[i] - (this.weight * this.xArr[i] + this.bias);

    w_deriv += -2 * wx * this.xArr[i];

    b_deriv += -2 * wx;

  }

  this.weight -= (w_deriv / this.points) * this.learnc;

  this.bias -= (b_deriv / this.points) * this.learnc;

}

} // End Trainer Object

sections.content:
Create a Trainer object that can take any number of (x,y) values in two arrays (xArr,yArr).

Set weight to zero and the bias to 1.

A learning constant (learnc) has to be set, and a cost variable must be defined:

Example

function Trainer(xArray, yArray) {

  this.xArr = xArray;

  this.yArr = yArray;

  this.points = this.xArr.length;

  this.learnc = 0.00001;

  this.weight = 0;

  this.bias = 1;

  this.cost;

We will now run a gradient descent.

The gradient descent algorithm should walk the cost function towards the best line.

Each iteration should update both m and b towards a line with a lower cost (error).

To do that, we add a train function that loops over all the data many times:

this.train = function(iter) {

  for (let i = 0; i < iter; i++) {

    this.updateWeights();

  }

  this.cost = this.costError();

}

The train function above should update the weights and biases in each iteration.

The direction to move is calculated using two partial derivatives:

this.updateWeights = function() {

  let wx;

  let w_deriv = 0;

  let b_deriv = 0;

  for (let i = 0; i < this.points; i++) {

    wx = this.yArr[i] - (this.weight * this.xArr[i] + this.bias);

    w_deriv += -2 * wx * this.xArr[i];

    b_deriv += -2 * wx;

  }

  this.weight -= (w_deriv / this.points) * this.learnc;

  this.bias -= (b_deriv / this.points) * this.learnc;

}

Library Code

function Trainer(xArray, yArray) {

  this.xArr = xArray;

  this.yArr = yArray;

  this.points = this.xArr.length;

  this.learnc = 0.00001;

  this.weight = 0;

  this.bias = 1;

  this.cost;

// Cost Function

this.costError = function() {

  total = 0;

  for (let i = 0; i < this.points; i++) {

    total += (this.yArr[i] - (this.weight * this.xArr[i] + this.bias)) **2;

  }

  return total / this.points;

}

// Train Function

this.train = function(iter) {

  for (let i = 0; i < iter; i++) {

    this.updateWeights();

  }

  this.cost = this.costError();

}

// Update Weights Function

this.updateWeights = function() {

  let wx;

  let w_deriv = 0;

  let b_deriv = 0;

  for (let i = 0; i < this.points; i++) {

    wx = this.yArr[i] - (this.weight * this.xArr[i] + this.bias);

    w_deriv += -2 * wx * this.xArr[i];

    b_deriv += -2 * wx;

  }

  this.weight -= (w_deriv / this.points) * this.learnc;

  this.bias -= (b_deriv / this.points) * this.learnc;

}

} // End Trainer Object

Now you can include the library in HTML:

<script src="myailib.js"></script>

